//! Closed validation of the serving declaration: the loopback listener, every
//! bound of the HTTP/1.1 exchange, the allowed origins and media types, and the
//! host-provided sections of the request frame.
//!
//! Declaration acceptance is not execution: the listener is generated by
//! `crate::server_host` and runs only in the built program.

use super::{
    field_name, FrameKind, FrameSection, HostField, HostKind, ServerApplication, ServerServing,
    ServingOrigin, MAXIMUM_CORPUS_BYTES, MAXIMUM_EXCHANGE_BYTES, MAXIMUM_VECTORS,
};
use crate::error::PrismError;
use std::collections::BTreeSet;

/// The only address a served application listens on.
pub const LOOPBACK: &str = "127.0.0.1";
/// Most allowed origins.
pub const MAXIMUM_ORIGINS: usize = 64;
/// Most media types in an `Accept` or `Content-Type` requirement.
pub const MAXIMUM_MEDIA_TYPES: usize = 16;
/// Most methods the media type requirements apply to.
pub const MAXIMUM_METHODS: usize = 8;
/// Most sections the host adds to the request frame.
pub const MAXIMUM_SECTIONS: usize = 16;
/// Most static values of a text list section.
pub const MAXIMUM_LIST_VALUES: usize = 64;
/// Most connections served at the same time.
pub const MAXIMUM_CONNECTIONS: u32 = 1024;
/// Longest time a request may take to arrive, one hour.
pub const MAXIMUM_READ_MILLIS: u32 = 3_600_000;
/// Smallest and largest stack of a connection thread.
pub const STACK_RANGE: (u32, u32) = (65_536, 1 << 30);
/// Largest request line.
pub const MAXIMUM_REQUEST_LINE: u32 = 1 << 20;
/// Largest number of field lines.
pub const MAXIMUM_HEADER_COUNT: u32 = 1024;
/// Largest total size of the field lines.
pub const MAXIMUM_HEADER_BYTES: u32 = 16 << 20;
/// What a frame section of an effect's request may draw from the connection.
pub const CONTEXT: [(&str, HostKind); 2] = [("peer", HostKind::Text), ("counted", HostKind::Flag)];

fn invalid(message: &str) -> PrismError {
    PrismError::new("PP2019", message)
}

fn token(value: &str) -> bool {
    !value.is_empty()
        && value.bytes().all(|byte| {
            byte.is_ascii_alphanumeric()
                || matches!(
                    byte,
                    b'!' | b'#'
                        | b'$'
                        | b'%'
                        | b'&'
                        | b'\''
                        | b'*'
                        | b'+'
                        | b'-'
                        | b'.'
                        | b'^'
                        | b'_'
                        | b'`'
                        | b'|'
                        | b'~'
                )
        })
}

/// A lowercase `type/subtype` with no parameters and no wildcard.
pub fn media_type(value: &str) -> bool {
    value.len() <= 127
        && value.split_once('/').is_some_and(|(kind, subtype)| {
            token(kind)
                && token(subtype)
                && !value.contains('*')
                && !value.bytes().any(|byte| byte.is_ascii_uppercase())
        })
}

fn host_text(value: &str) -> bool {
    let bracketed = value.starts_with('[') && value.ends_with(']');
    !value.is_empty()
        && value.len() <= 253
        && value.bytes().all(|byte| {
            byte.is_ascii_lowercase()
                || byte.is_ascii_digit()
                || matches!(byte, b'.' | b'-')
                || (bracketed && matches!(byte, b'[' | b']' | b':'))
        })
        && (bracketed || !value.contains(['[', ']', ':']))
}

fn printable(value: &str, maximum: usize) -> bool {
    !value.is_empty()
        && value.len() <= maximum
        && value.bytes().all(|byte| (0x20..0x7f).contains(&byte))
}

fn origin(value: &ServingOrigin) -> bool {
    matches!(value.scheme.as_str(), "http" | "https")
        && host_text(&value.host)
        && value.port <= 65_535
}

fn number(value: &str, kind: FrameKind) -> bool {
    match kind {
        FrameKind::U32 => value.parse::<u32>().is_ok_and(|n| n.to_string() == value),
        _ => value.parse::<u64>().is_ok_and(|n| n.to_string() == value),
    }
}

fn kind_of(kind: HostKind) -> Option<FrameKind> {
    match kind {
        HostKind::U32 => Some(FrameKind::U32),
        HostKind::U64 => Some(FrameKind::U64),
        HostKind::Bytes => Some(FrameKind::Bytes),
        HostKind::Text => Some(FrameKind::Text),
        HostKind::Flag => None,
    }
}

/// Largest encoded size of one section, in bytes.
fn section_maximum(application: &ServerApplication, section: &FrameSection) -> u64 {
    if let Some(effect) = application
        .host
        .effects
        .iter()
        .find(|effect| effect.name == section.effect)
    {
        return match section.kind {
            FrameKind::U32 => 4,
            FrameKind::U64 => 8,
            _ => 4 + u64::from(effect.result_maximum),
        };
    }
    match section.kind {
        FrameKind::U32 => 4,
        FrameKind::U64 => 8,
        FrameKind::Bytes => 4,
        FrameKind::Text => 4 + section.values.first().map_or(0, String::len) as u64,
        FrameKind::TextList => {
            4 + section
                .values
                .iter()
                .map(|value| 4 + value.len() as u64)
                .sum::<u64>()
        }
    }
}

/// Largest request frame the listener can build under the declared bounds: the
/// method and target with their lengths, the field lines with their lengths, the
/// body, and every host-provided section.
pub fn frame_maximum(application: &ServerApplication, serving: &ServerServing) -> u64 {
    8 + u64::from(serving.request_line_maximum)
        + 4
        + u64::from(serving.header_bytes_maximum)
        + 8 * u64::from(serving.header_count_maximum)
        + 4
        + u64::from(serving.body_maximum)
        + serving
            .frame
            .iter()
            .map(|section| section_maximum(application, section))
            .sum::<u64>()
}

fn request_record(fields: &[HostField]) -> bool {
    let mut names = BTreeSet::new();
    fields.iter().all(|field| {
        CONTEXT
            .iter()
            .any(|(name, kind)| *name == field.name && *kind == field.kind)
            && names.insert(field.name.as_str())
    })
}

fn section(
    application: &ServerApplication,
    serving: &ServerServing,
    value: &FrameSection,
) -> Result<(), PrismError> {
    if !field_name(&value.name) {
        return Err(invalid(
            "a frame section is named in lowercase letters, digits and inner underscores",
        ));
    }
    let from_effect = !value.effect.is_empty() || !value.field.is_empty();
    let from_model = !value.values.is_empty();
    if from_effect == from_model {
        return Err(invalid(
            "a frame section comes from exactly one source: a result field of a declared effect, or model values",
        ));
    }
    if from_effect {
        let effect = application
            .host
            .effects
            .iter()
            .find(|effect| effect.name == value.effect)
            .ok_or_else(|| invalid("a frame section names an effect that is not declared"))?;
        let field = effect
            .result
            .iter()
            .find(|field| field.name == value.field)
            .ok_or_else(|| invalid("a frame section names a result field the effect lacks"))?;
        if kind_of(field.kind) != Some(value.kind) {
            return Err(invalid(
                "a frame section has the kind of the result field it reads",
            ));
        }
        if !request_record(&effect.request) {
            return Err(invalid(
                "an effect that fills the frame may ask only for the peer address and the counted flag",
            ));
        }
        if effect
            .request
            .iter()
            .any(|field| field.name == "counted" && serving.counted_field.is_empty())
        {
            return Err(invalid(
                "an effect that asks for the counted flag needs a counted field and value",
            ));
        }
        return Ok(());
    }
    let valid = match value.kind {
        FrameKind::U32 | FrameKind::U64 => {
            value.values.len() == 1 && number(&value.values[0], value.kind)
        }
        FrameKind::Text => value.values.len() == 1 && printable(&value.values[0], 4096),
        FrameKind::TextList => {
            value.values.len() <= MAXIMUM_LIST_VALUES
                && value.values.iter().all(|text| host_text(text))
        }
        FrameKind::Bytes => false,
    };
    if valid {
        Ok(())
    } else {
        Err(invalid(
            "model values of a frame section are one number, one text or a list of host names; bytes come only from an effect",
        ))
    }
}

fn media_types(values: &[String]) -> bool {
    let mut seen = BTreeSet::new();
    values.len() <= MAXIMUM_MEDIA_TYPES
        && values
            .iter()
            .all(|value| media_type(value) && seen.insert(value.as_str()))
}

fn bounds(value: &ServerServing) -> Result<(), PrismError> {
    let within = |number: u32, low: u32, high: u32| (low..=high).contains(&number);
    if value.address != LOOPBACK {
        return Err(invalid(
            "a served application listens on 127.0.0.1 only; no other address is admitted",
        ));
    }
    if value.port > 65_535
        || !within(value.connection_maximum, 1, MAXIMUM_CONNECTIONS)
        || !within(value.read_timeout_millis, 1, MAXIMUM_READ_MILLIS)
        || !within(value.root_stack_bytes, STACK_RANGE.0, STACK_RANGE.1)
        || !within(value.request_line_maximum, 16, MAXIMUM_REQUEST_LINE)
        || !within(value.header_count_maximum, 1, MAXIMUM_HEADER_COUNT)
        || !within(value.header_bytes_maximum, 1, MAXIMUM_HEADER_BYTES)
        || !within(value.body_maximum, 1, MAXIMUM_EXCHANGE_BYTES)
    {
        return Err(invalid(
            "the listener port, connections, read time, root stack and request bounds must be within their closed ranges and none may be zero",
        ));
    }
    Ok(())
}

fn requirements(value: &ServerServing) -> Result<(), PrismError> {
    let mut origins = BTreeSet::new();
    if value.origins.len() > MAXIMUM_ORIGINS
        || value.origins.iter().any(|allowed| {
            !origin(allowed) || !origins.insert((&allowed.scheme, &allowed.host, allowed.port))
        })
    {
        return Err(invalid(
            "allowed origins are at most 64 unique http or https hosts with a port or 0 for any",
        ));
    }
    let mut methods = BTreeSet::new();
    if !media_types(&value.accept)
        || !media_types(&value.content_types)
        || value.enforced_methods.len() > MAXIMUM_METHODS
        || value.enforced_methods.iter().any(|method| {
            method.len() > 16
                || method.is_empty()
                || !method.bytes().all(|byte| byte.is_ascii_uppercase())
                || !methods.insert(method.as_str())
        })
        || value.enforced_methods.is_empty()
            != (value.accept.is_empty() && value.content_types.is_empty())
    {
        return Err(invalid(
            "required media types are unique lowercase type/subtype values, and the methods they apply to are named exactly when some are required",
        ));
    }
    if value.counted_field.is_empty() != value.counted_value.is_empty()
        || (!value.counted_field.is_empty()
            && (value.counted_field.len() > 64
                || !token(&value.counted_field)
                || !printable(&value.counted_value, 256)))
    {
        return Err(invalid(
            "a counted field is a header name and a printable value, both set or both empty",
        ));
    }
    Ok(())
}

fn vectors(application: &ServerApplication, value: &ServerServing) -> Result<(), PrismError> {
    let mut requests = BTreeSet::new();
    let mut total = 0usize;
    if value.vectors.is_empty()
        || value.vectors.len() > MAXIMUM_VECTORS
        || value.vectors.iter().any(|vector| {
            total = total
                .saturating_add(vector.request.len())
                .saturating_add(vector.response.len());
            usize::try_from(vector.vector)
                .map_or(true, |index| index >= application.acceptance_vectors.len())
                || total > MAXIMUM_CORPUS_BYTES
                || !requests.insert(&vector.request)
        })
    {
        return Err(invalid(
            "a served application needs bounded unique HTTP vectors, each naming an existing frame vector",
        ));
    }
    Ok(())
}

/// Validate the serving record of `application`, when there is one.
///
/// # Errors
/// Returns `PP2019` for a record that is not the closed declaration.
pub fn validate(application: &ServerApplication) -> Result<(), PrismError> {
    if application.serving.len() > 1 {
        return Err(invalid(
            "a server application declares at most one serving record",
        ));
    }
    let Some(serving) = application.serving.first() else {
        return Ok(());
    };
    bounds(serving)?;
    requirements(serving)?;
    let mut names = BTreeSet::new();
    if serving.frame.len() > MAXIMUM_SECTIONS
        || serving
            .frame
            .iter()
            .any(|value| !names.insert(value.name.as_str()))
    {
        return Err(invalid(
            "a frame has at most 16 sections with distinct names",
        ));
    }
    for value in &serving.frame {
        section(application, serving, value)?;
    }
    vectors(application, serving)?;
    if frame_maximum(application, serving) > u64::from(application.request_maximum) {
        return Err(invalid(
            "the request frame under the declared bounds can be larger than the exchange request maximum",
        ));
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_frame_effect_is_never_an_effect_the_core_may_request() {
        let plain = crate::server_host::tests::model();
        assert!(plain.frame_effects().is_empty());
        assert_eq!(plain.core_effects().count(), 3);
        assert!(plain.performs_effects());
        let served = crate::server_host::serving_tests::served_model();
        let frame = served.frame_effects();
        assert_eq!(
            frame.iter().copied().collect::<Vec<_>>(),
            ["secret.statekey", "tool.calls"]
        );
        assert_eq!(served.host.effects.len(), 2);
        assert!(served
            .core_effects()
            .all(|effect| !frame.contains(effect.name.as_str())));
        // Declared for the frame only, they leave the core a plain frame function.
        assert!(!served.performs_effects());
        assert_eq!(served.host.effect_budget, 0);
        validate(&served).unwrap();
    }

    #[test]
    fn media_types_are_lowercase_without_parameters_or_wildcards() {
        assert!(media_type("application/json"));
        assert!(media_type("text/event-stream"));
        for bad in [
            "*/*",
            "text/*",
            "Application/json",
            "json",
            "a/b;q=1",
            "a/",
            "/b",
            "",
        ] {
            assert!(!media_type(bad), "{bad}");
        }
    }
}
